// <summary>
///     The <c>AVASalesTableFrm_SalesTableDS_CustAccountFld_Extension</c> class is the extension for <c>SalesTable</c>
///     AVA - Schneider 19.02.2024
/// </summary>
[ExtensionOf(formDataFieldStr(SalesTable, SalesTable, CustAccount))]
final class AVASalesTableFrm_SalesTableDS_CustAccountFld_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>modified</c> method.
///     AVA - Schneider 19.02.2024
/// </summary>
public void modified()
{
    DialogButton    locDialogButton;
    FormDataSource  locSalesTableDS;
    SalesTable      locSalesTable;
    SalesTable      locSalesTableOrig;
    boolean         locSalesTableModified;

    FormDataSource  locLogisticsPostalAddressDeliveryHeaderDS;

    locSalesTableDS     = element.SalesTable_DS;
    locSalesTable       = locSalesTableDS.cursor();
    locSalesTableOrig   = locSalesTable.orig();

    locDialogButton = Box::yesNoCancel("@NDX:NXAWantToChangeDeliveryAddress", DialogButton::No, "@NDX:NXASalesOrderHeaderChange");
    switch(locDialogButton)
    {
        /*
        case DialogButton::Yes:
            // standard delivery address of customer
            if(locSalesTable.CustAccount)
            {
                locSalesTable.DeliveryPostalAddress = CustTable::find(locSalesTable.CustAccount).mcrDefaultDeliveryPostalAddress().RecId;
            }
            break;

        case DialogButton::No:
            // keep allready set delivery address
            locSalesTable.DeliveryPostalAddress = locSalesTableOrig.DeliveryPostalAddress;
            locLogisticsPostalAddressDeliveryHeaderDS   = element.LogisticsPostalAddressDeliveryHeader_DS;
            locLogisticsPostalAddressDeliveryHeaderDS.executeQuery();
            break;
        */
        case DialogButton::Cancel:
            // keep original CustAccount
            locSalesTable.CustAccount = locSalesTableOrig.CustAccount;
            break;

        default:
        // do nothing
    }

    next modified();

    switch(locDialogButton)
    {
        case DialogButton::Yes:
            // standard delivery address of customer
            if(locSalesTable.CustAccount)
            {
                locSalesTable.DeliveryPostalAddress = CustTable::find(locSalesTable.CustAccount).mcrDefaultDeliveryPostalAddress().RecId;
                locSalesTableModified               = true;
            }
            break;

        case DialogButton::No:
            // keep allready set delivery address
            locSalesTable.DeliveryName          = locSalesTableOrig.DeliveryName;
            locSalesTable.DeliveryPostalAddress = locSalesTableOrig.DeliveryPostalAddress;
            locSalesTableModified               = true;
            break;
        /*
        case DialogButton::Cancel:
            // keep original CustAccount
            locSalesTable.CustAccount = locSalesTableOrig.CustAccount;
            break;
        */
        default:
        // do nothing
    }
    locSalesTableDS.refresh();
}
